/* GLB 모드 — 캐릭터 위 네임태그만 DOM 마커 */
.map-view__glb-nametag-host {
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: flex-end;
  /* 이름표는 표시 전용인데 Mapbox `.mapboxgl-marker` 와 특이도가 같아 밀리고 있었다.
     라이더를 화면 아래로 내린 뒤(anchor 0.6) 표고 그래프 면까지 들어와 15 지점을
     막는 것이 계약에 걸렸다(2026-09-18). */
  pointer-events: none !important;
