/* Self-location — 화면 고정 px, live nametag·peer 와 별 요소 */
.map-view__self-location-marker {
  background: transparent !important;
  border: none !important;
  /* `!important` 인 이유는 위 두 줄과 같다 — Mapbox 자체 `.mapboxgl-marker` 규칙이
     같은 특이도(0,1,0)로 부딪혀 우리 선언이 밀린다. 실측에서 이 호스트가 표고 그래프
     면 안에서 지도 조작을 3 지점 막고 있었다(elevation-area-scan.json). 내 위치 표식은
     표시 전용이므로 못을 박는다. */
  pointer-events: none !important;
}

.map-view__self-location-host {
  width: 28px;
  height: 28px;
  /* position 은 Mapbox `.mapboxgl-marker`(absolute) 그대로 — relative 로 덮으면 마커끼리 문서 흐름에
     쌓여, 앞 마커 높이만큼 밀린다(동행 점이 내 점 28px 만큼 아래로 내려갔다, 2026-10-08). */
  pointer-events: none !important;
}

.map-view__self-location-pulse {
  /* 장식(펄스 링)일 뿐인데 실측에서 터치를 잡고 있었다 — 부모 2개가 이미 none 이지만
     Mapbox 자체 `.mapboxgl-marker` 규칙과 같은 특이도로 부딪힌다. 여기서 못을 박는다. */
  pointer-events: none;
  position: absolute;
  inset: 0;
  border-radius: 50%;
  /*
   * 흰 링 + 파란 테 두 겹 — 위성(어두움)에선 흰색이, Outdoors(밝음)에선 파랑이 대비를 맡는다.
   * 종전 반투명 파랑 원판은 위성 사진에 묻혀 보이지 않았다(2026-10-07 Chief).
   */
  background: rgba(59, 130, 246, 0.3);
  border: 2px solid rgba(255, 255, 255, 0.95);
  box-shadow: 0 0 0 1.5px rgba(29, 78, 216, 0.9);
  box-sizing: border-box;
  animation: map-view-self-location-pulse var(--rtw-ride-pulse-period, 2.2s) ease-out infinite;
}

.map-view__self-location-core {
  position: absolute;
  inset: 6px;
  border-radius: 50%;
  background: #1d4ed8;
  border: 2px solid #fff;
  box-shadow:
    0 0 0 1px rgba(29, 78, 216, 0.45),
    0 2px 8px rgba(15, 23, 42, 0.35);
}

.map-view__self-location-bearing {
  position: absolute;
  inset: 0;
  transform-origin: 50% 50%;
  opacity: 0;
  pointer-events: none;
  transition: opacity 0.15s ease;
}

.map-view__self-location-bearing-chevron {
  position: absolute;
  left: 50%;
  top: -1px;
  width: 0;
  height: 0;
  margin-left: -4px;
  border-left: 4px solid transparent;
  border-right: 4px solid transparent;
  border-bottom: 7px solid #fff;
  filter: drop-shadow(0 0 1px rgba(15, 23, 42, 0.55));
}

/* 퍼지는 범위 28px → ~73px(종전 ~42px). 위상·박자는 그대로(ridePulse.ts) */
@keyframes map-view-self-location-pulse {
  0% {
    transform: scale(0.8);
    opacity: 0.95;
  }
  75% {
    transform: scale(2.6);
    opacity: 0;
  }
  100% {
    transform: scale(2.6);
    opacity: 0;
  }
}

/* 동행 위치 — 내 점(28px·파랑·×2.6)보다 작게(18px·청록·×1.9). 색은 동행 이름표와 같다 */
.map-view__peer-location-marker {
  background: transparent !important;
  border: none !important;
  pointer-events: none !important;
}

.map-view__peer-location-host {
  width: 18px;
  height: 18px;
  /* position 은 Mapbox `.mapboxgl-marker`(absolute) 그대로 — relative 로 덮으면 마커끼리 문서 흐름에
     쌓여, 앞 마커 높이만큼 밀린다(동행 점이 내 점 28px 만큼 아래로 내려갔다, 2026-10-08). */
  pointer-events: none !important;
}

.map-view__peer-location-pulse {
  pointer-events: none;
  position: absolute;
  inset: 0;
  border-radius: 50%;
  background: rgba(20, 184, 166, 0.3);
  border: 1.5px solid rgba(255, 255, 255, 0.95);
  box-shadow: 0 0 0 1px rgba(15, 118, 110, 0.9);
  box-sizing: border-box;
  animation: map-view-peer-location-pulse var(--rtw-ride-pulse-period, 2.2s) ease-out infinite;
}

.map-view__peer-location-core {
  position: absolute;
  inset: 4px;
  border-radius: 50%;
  background: #0f766e;
  border: 2px solid #fff;
  box-shadow: 0 1px 4px rgba(15, 23, 42, 0.35);
}

@keyframes map-view-peer-location-pulse {
  0% {
    transform: scale(0.8);
    opacity: 0.9;
  }
  75% {
    transform: scale(1.9);
    opacity: 0;
  }
  100% {
    transform: scale(1.9);
    opacity: 0;
  }
}

@media (prefers-reduced-motion: reduce) {
  .map-view__peer-location-pulse {
    animation: none;
    opacity: 0.35;
  }

  .map-view__self-location-pulse {
    animation: none;
    opacity: 0.35;
    transform: scale(1.1);
  }
}

