.map-view .map-view__pick-popup.mapboxgl-popup-anchor-bottom .mapboxgl-popup-tip {
  border-top-color: #FFFFFF;
}
.map-view .map-view__pick-popup.mapboxgl-popup-anchor-left .mapboxgl-popup-tip {
  border-right-color: #FFFFFF;
}
.map-view .map-view__pick-popup.mapboxgl-popup-anchor-right .mapboxgl-popup-tip {
  border-left-color: #FFFFFF;
}

.map-view .map-view__pick-popup .mapboxgl-popup-close-button {
  color: #475569;
  font-size: 1rem;
  line-height: 1;
  padding: 0;
  width: 1.65rem;
  height: 1.65rem;
  right: 0.2rem;
  top: 0.2rem;
  border-radius: 50%;
  background: #F1F5F9;
  border: 1px solid #CBD5E1;
  box-shadow: none;
  display: flex;
  align-items: center;
  justify-content: center;
}

.map-view .map-view__pick-popup .mapboxgl-popup-close-button:hover {
  color: #1F2937;
  background: #EFF6FF;
}

.map-view__pick {
  padding: 0.45rem 0.55rem 0.5rem;
  min-width: 13.5rem;
  max-width: 20rem;
  box-sizing: border-box;
  color: #1F2937;
}

.map-view__pick-drag-handle {
  touch-action: none;
  cursor: grab;
  user-select: none;
}

/*
 * 제목 행이 스스로 ✕ 자리를 비우므로(`.map-view__pick-token` padding-right) 핸들 전체를
 * 밀 필요가 없다 — 주소·좌표는 둘째 줄부터라 ✕ 와 만나지 않는다.
 */

.map-view__pick-address {
  font-size: calc(0.82rem - 2pt);
  font-weight: 700;
  line-height: 1.3;
  color: #1F2937;
  word-break: break-word;
}

.map-view__pick-meta {
  margin-top: 0.15rem;
  font-family: ui-monospace, SFMono-Regular, Menlo, Monaco, Consolas, monospace;
  font-size: 0.68rem;
  letter-spacing: 0.01em;
  color: rgba(71, 85, 105, 0.78);
  line-height: 1.35;
  word-break: break-all;
}

.map-view__pick-actions {
  display: flex;
  gap: 0.28rem;
  margin-top: 0.22rem;
}

.map-view__pick-actions--pin-row {
  position: sticky;
  top: 0;
  z-index: 2;
  background: #FFFFFF;
  flex-wrap: nowrap;
  align-items: stretch;
  gap: 0.24rem;
  overflow-x: auto;
  -webkit-overflow-scrolling: touch;
  scrollbar-width: thin;
}

.map-view__pick-actions--pin-row .map-view__pick-btn {
  flex: 1 1 0;
  min-width: 0;
  padding: 0.24rem 0.32rem;
  font-size: 0.7rem;
}

/* 지시30 — 패널 접기. hidden 내용이 flex/grid display 에 덮이지 않게 scoped 규칙. */
.map-view__pick [hidden] {
  display: none !important;
}

/* 지시34 — 위치/거리 별도 화면. 같은 wrap, 내용만 교체. 토글/toolbar는 제거. */
.map-view__pick-route-view {
  min-width: 0;
  max-width: 100%;
}

.map-view__pick-route-view--location {
  margin-top: 0.06rem;
}

.map-view__pick-route-view--location .map-view__pick-actions--pin-row {
  margin-top: 0.08rem;
}

/* 재지시35 — '거리 ›' 진입. profile row 끝에 붙고 별도 중간행 없음. 44px는 이 버튼만.
 * base(.map-view__pick-btn min-height:0)가 뒤에서 덮어 specificity를 (0,2,0)으로 올려
 * min-height/flex/패딩/배경/색을 보존한다. 순서와 무관하게 이긴다. */
.map-view__pick .map-view__pick-btn--route-enter {
  display: flex;
  align-items: center;
  justify-content: center;
  flex: 1 1 0;
  min-width: 44px;
  min-height: 44px;
  align-self: center;
  padding: 0.26rem 0.5rem;
  background: #EFF6FF;
  border-color: #2563EB;
  color: #1D4ED8;
  white-space: nowrap;
}

.map-view__pick .map-view__pick-btn--route-enter:hover:not(:disabled) {
  background: #DBEAFE;
  border-color: #1D4ED8;
}

/* 재지시35 — 거리 화면 상단. '‹ 위치 선택' 복귀 + 제목 한 행(별도 중간행 없음).
 * base 덮음 방지용 (0,2,0). back은 약한 배경 + 작은 radius(알약 아님)로 제목과 구분.
 * 제목은 별도 텍스트, 좁으면 제목만 줄바꿈하고 생략(ellipsis)하지 않는다. */
.map-view__pick-route-distance-head {
  display: flex;
  align-items: center;
  gap: 0.4rem;
  min-width: 0;
  max-width: 100%;
  margin-top: 0.06rem;
}

.map-view__pick .map-view__pick-btn--route-back {
  display: flex;
  align-items: center;
  justify-content: center;
  flex: 0 0 auto;
  min-width: 44px;
  min-height: 44px;
  padding: 0.26rem 0.5rem;
  background: #F1F5F9;
  border-color: #CBD5E1;
  border-radius: 10px;
  color: #1F2937;
  white-space: nowrap;
}

.map-view__pick .map-view__pick-btn--route-back:hover:not(:disabled) {
  background: #EFF6FF;
  border-color: #CBD5E1;
}

/* 지시38 — 이중 캐럿 disclosure 행. 두 패널 사이 비drag 영역, 전체폭 44px 투명 얇은 영역.
 * 테두리/알약 배경/큰 카드 없음. 기존 폰트/버튼 크기 축소 없음. SVG stroke 파랑은 DOM 지정. */
.map-view__pick .map-view__pick-caret {
  display: flex;
  align-items: center;
  justify-content: flex-start;
  width: 100%;
  min-height: 16.8px;
  height: 16.8px;
  padding: 0;
  margin: 0;
  background: transparent;
  border: 0;
  border-radius: 0;
  cursor: pointer;
  appearance: none;
}

.map-view__pick .map-view__pick-caret:hover {
  background: transparent;
}

.map-view__pick .map-view__pick-caret:focus-visible {
  outline: 2px solid #2563EB;
  outline-offset: 1px;
  border-radius: 4px;
}

.map-view__pick .map-view__pick-caret-ico {
  width: 20px;
  height: 14px;
  display: block;
  flex-shrink: 0;
}

.map-view__pick-route-distance-title {
  margin: 0;
  flex: 1 1 auto;
  min-width: 0;
  overflow: visible;
  text-overflow: clip;
  white-space: normal;
  overflow-wrap: break-word;
  font-size: 0.72rem;
  font-weight: 700;
  line-height: 1.3;
  color: #1F2937;
}

/* 지시34 — 작은 출발 요약. 실제 수단과 동기화, 클릭 지점 주소 오표시 없음. */
.map-view__pick-route-distance-summary {
  margin: 0.1rem 0 0;
  font-size: 0.68rem;
  line-height: 1.35;
  color: rgba(71, 85, 105, 0.9);
}

.map-view__pick-btn {
  flex: 1;
  appearance: none;
  border: 1px solid transparent;
  font: inherit;
  font-size: 0.74rem;
  font-weight: 700;
  padding: 0.26rem 0.42rem;
  min-height: 0;
  line-height: 1.25;
  border-radius: 999px;
  cursor: pointer;
  transition:
    background 0.15s ease,
    border-color 0.15s ease,
    box-shadow 0.15s ease,
    opacity 0.15s ease;
}

.map-view__pick-btn:active:not(:disabled) {
  transform: scale(0.98);
}

.map-view__pick-btn:disabled {
  opacity: 0.38;
  cursor: not-allowed;
}

.map-view__pick-btn--start {
  background: #2563EB;
  border-color: #2563EB;
  color: #FFFFFF;
}

.map-view__pick-btn--start:hover:not(:disabled) {
  background: #1D4ED8;
  border-color: #1D4ED8;
}

.map-view__pick-btn--end {
  background: #2563EB;
  border-color: #2563EB;
  color: #FFFFFF;
}

.map-view__pick-btn--end:hover:not(:disabled) {
  background: #1D4ED8;
  border-color: #1D4ED8;
}

.map-view__pick-btn--wp {
  background: #F1F5F9;
  border-color: #CBD5E1;
  color: #1F2937;
}

.map-view__pick-btn--wp:hover:not(:disabled) {
  background: #EFF6FF;
  border-color: #2563EB;
}

.map-view__pick-profile-section {
  margin-top: 0.14rem;
}

/*
 * 팝업 제목 행(2026-09-16 Chief). 주소보다 **위**에 온다.
 * 짧은 문구라 오른쪽 끝 닫기 ✕ 와 부딪히지 않고, 긴 주소는 둘째 줄로 내려가 ✕ 를 덮지 않는다.
 * 상자를 벗고 아래 구분선만 남겨 「제목 → 본문」으로 읽히게 한다.
 */
.map-view__pick-token {
  margin: 0 0 0.2rem;
  /* 오른쪽은 닫기 ✕(1.65rem + 0.2rem) 자리 */
  padding: 0 1.95rem 0.22rem 0;
  border-bottom: 1px solid #CBD5E1;
}

.map-view__pick-token-line {
  margin: 0;
  font-size: 0.72rem;
  font-weight: 700;
  letter-spacing: 0.01em;
  color: #1F2937;
  line-height: 1.3;
  word-break: keep-all;
}

/* 잔액이 아직 없을 때 — 제목만. 상태 색을 쓰지 않는다 */
.map-view__pick-token-line--title {
  color: rgba(31, 41, 55, 0.92);
}

.map-view__pick-token-line--insufficient {
  color: #DC2626;
}

.map-view__pick-token-line--spend {
  color: #16a34a;
}

.map-view__pick-token-line--pending {
  color: rgba(37, 99, 235, 0.9);
}

/* 재지시35 — 공통 headerRow: token + 경로 삭제 나란히, 두 모드 공통. 닫기 ✕ 자리(약1.7rem:
 * 1.65rem 버튼 + 0.2rem 오프셋)는 이 행이 확보하고, token 기존 우측 패딩은 이중이 되지 않게 0으로.
 * 구분선은 행 전체에 하나만. 삭제 버튼 라벨/폰트·크기는 기존 그대로, token 피드백은 flex로 전체 표시. */
.map-view__pick-header-row {
  display: flex;
  align-items: center;
  gap: 0.4rem;
  min-width: 0;
  max-width: 100%;
  margin: 0 0 0.2rem;
  padding: 0 1.85rem 0.22rem 0;
  border-bottom: 1px solid #CBD5E1;
}

.map-view__pick-header-row .map-view__pick-token {
  flex: 1 1 auto;
  min-width: 0;
  margin: 0;
  padding: 0;
  border-bottom: 0;
}

.map-view__pick-header-row .map-view__pick-btn--clear-route {
  margin-left: 0;
  flex: 0 0 auto;
}

.map-view__pick-btn--clear-route {
  margin-left: auto;
  flex: 0 0 auto;
  appearance: none;
  font: inherit;
  font-size: 0.66rem;
  font-weight: 650;
  padding: 0.2rem 0.48rem;
  line-height: 1.25;
  border-radius: 999px;
  cursor: pointer;
  border: 1px solid #CBD5E1;
  background: #FFFFFF;
  color: #475569;
  transition:
    background 0.15s ease,
    border-color 0.15s ease,
    opacity 0.15s ease;
}

.map-view__pick-btn--clear-route:hover {
  background: #EFF6FF;
  border-color: #CBD5E1;
}

.map-view__pick-btn--clear-route:active {
  transform: scale(0.98);
}

.map-view__pick-actions--profile {
  display: flex;
  flex-wrap: nowrap;
  align-items: center;
  gap: 0.28rem;
  margin-top: 0;
}

.map-view__pick-btn--profile {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  flex: 0 0 auto;
  box-sizing: border-box;
  width: 2.35rem;
  height: 2.35rem;
  min-width: 2.35rem;
  min-height: 2.35rem;
  max-width: 2.35rem;
  max-height: 2.35rem;
  padding: 0;
  border-radius: 50%;
  background: #F1F5F9;
  border-color: transparent;
  color: #475569;
  font-size: 0.72rem;
  line-height: 1;
}

.map-view__pick-profile-ico {
  width: 1.22rem;
  height: 1.22rem;
  display: block;
  flex-shrink: 0;
}

.map-view__pick-btn--profile:hover:not(:disabled) {
  background: #EFF6FF;
  border-color: transparent;
}

.map-view__pick-btn--profile:focus-visible {
  outline: 2px solid #2563EB;
  outline-offset: 2px;
}

.map-view__pick-btn--profile.is-active {
  background: #2563EB;
  border-color: #2563EB;
  color: #FFFFFF;
}

/* 선택된 수단은 hover 중에도 파랑을 유지한다 — hover 규칙(구 CSS 그대로)이
   배경을 덮으면 흰 아이콘이 옅은 바탕에 묻혀 읽히지 않는다(실측). 색 성분만 지정. */
.map-view__pick-btn--profile.is-active:hover:not(:disabled) {
  background: #1D4ED8;
  border-color: #1D4ED8;
  color: #FFFFFF;
}

.map-view__pick-auto-route {
  /* 지시34 — 거리 화면 컨테이너. 위치 화면과 동시 노출 없이 내용만 교체. */
  margin-top: 0.06rem;
  padding-top: 0;
  border-top: 0;
}

.map-view__pick-sr-only {
  position: absolute;
  width: 1px;
  height: 1px;
  padding: 0;
  margin: -1px;
  overflow: hidden;
  clip: rect(0, 0, 0, 0);
  white-space: nowrap;
  border: 0;
}

.map-view__pick-distance-row {
  --pick-distance-control-height: 1.625rem;
  display: grid;
  grid-template-columns: auto auto 1fr auto auto;
  align-items: center;
  gap: 0.22rem;
}

.map-view__pick-distance-mode {
  display: inline-flex;
  align-items: center;
  gap: 0.12rem;
  margin: 0;
  font-size: 0.65rem;
  font-weight: 600;
  color: rgba(71, 85, 105, 0.9);
  cursor: pointer;
  flex-shrink: 0;
  user-select: none;
}

.map-view__pick-distance-mode-checkbox {
  width: 0.9rem;
  height: 0.9rem;
  margin: 0;
  flex-shrink: 0;
  accent-color: #2563EB;
}

.map-view__pick-distance-mode-label {
  line-height: 1;
  white-space: nowrap;
}

/*
 * 지시34 — 한행 '목표 거리 −/숫자/km/＋'. DOM 순서(계약 고정)는 그대로 두고
 * order로만 시각 배열한다. 기존 버튼/폰트 크기는 그대로.
 */
.map-view__pick-distance-caption {
  order: 0;
  font-size: 0.68rem;
  font-weight: 700;
  line-height: 1.25;
  color: #1F2937;
  white-space: nowrap;
}

.map-view__pick-distance-row .map-view__pick-distance-step--minus {
  order: 1;
}

.map-view__pick-distance-row .map-view__pick-distance-number {
  order: 2;
}

.map-view__pick-distance-unit {
  order: 3;
  font-size: 0.68rem;
  line-height: 1.25;
  color: rgba(71, 85, 105, 0.9);
}

.map-view__pick-distance-row .map-view__pick-distance-step--plus {
  order: 4;
}

.map-view__pick-distance-row .map-view__pick-distance-chips {
  order: 5;
}

.map-view__pick-distance-row .map-view__pick-distance-eta {
  order: 6;
}

.map-view__pick-distance-row--disabled .map-view__pick-distance-slider {
  opacity: 0.42;
}

.map-view__pick-distance-step {
  appearance: none;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  box-sizing: border-box;
  width: var(--pick-distance-control-height);
  height: var(--pick-distance-control-height);
  min-width: var(--pick-distance-control-height);
  min-height: var(--pick-distance-control-height);
  padding: 0;
  border-radius: 0.35rem;
  border: 1px solid #CBD5E1;
  background: #F1F5F9;
  color: #1F2937;
  font-size: 0.82rem;
  font-weight: 700;
  line-height: 1;
  cursor: pointer;
}

.map-view__pick-distance-step:disabled {
  opacity: 0.35;
  cursor: not-allowed;
}

.map-view__pick-distance-slider {
  width: 100%;
  min-width: 0;
  accent-color: #2563EB;
}

.map-view__pick-distance-number {
  width: 2.65rem;
  height: var(--pick-distance-control-height);
  box-sizing: border-box;
  padding: 0 0.22rem;
  font-size: 0.68rem;
  color: #1F2937;
  background: #FFFFFF;
  border: 1px solid #CBD5E1;
  border-radius: 0.35rem;
  text-align: right;
}

.map-view__pick-distance-number:disabled {
  opacity: 0.42;
  cursor: not-allowed;
}

.map-view__pick-auto-route-status-slot {
  min-height: 0.92rem;
  margin: 0.12rem 0 0;
}

.map-view__pick-auto-route-status {
  margin: 0;
  min-height: inherit;
  color: rgba(71, 85, 105, 0.9);
  font-size: 0.68rem;
  line-height: 1.35;
}

.map-view__pick-auto-route-status--idle {
  visibility: hidden;
}

.map-view__pick-auto-route-status--searching {
  color: #B45309;
}

.map-view__pick-auto-route-status--failed {
  color: #DC2626;
}

.map-view__pick-auto-route-status--found {
  color: #16a34a;
}

.map-view__auto-route-status {
  display: grid;
  gap: 0.42rem;
  min-width: 14rem;
}

.map-view__auto-route-status-title {
  margin: 0;
  color: #1F2937;
  font-size: 0.86rem;
  font-weight: 800;
}

.map-view__auto-route-status-actions {
  display: flex;
  gap: 0.35rem;
}

.map-view__pick-btn--auto-cancel {
  flex: 0 0 auto;
  border-radius: 0.65rem;
  padding: 0.48rem 0.65rem;
  color: #475569;
  background: #F1F5F9;
  border-color: #CBD5E1;
}

.map-view__auto-route-progress {
  height: 0.18rem;
  overflow: hidden;
  border-radius: 999px;
  background: #F1F5F9;
}

.map-view__auto-route-progress::after {
  content: "";
  display: block;
  width: 42%;
  height: 100%;
  border-radius: inherit;
  background: #2563EB;
  animation: map-view-auto-route-progress 1s ease-in-out infinite alternate;
}

@keyframes map-view-auto-route-progress {
  from {
    transform: translateX(0);
  }
  to {
    transform: translateX(138%);
  }
}

.map-view__auto-route-click-debug-marker-host {
  pointer-events: none;
}

.map-view__auto-route-click-debug-host {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 0.15rem;
  pointer-events: none;
}

.map-view__auto-route-click-debug-marker {
  position: relative;
  display: grid;
  place-items: center;
  width: 1.35rem;
  height: 1.35rem;
  border: 2px solid #d946ef;
  border-radius: 999px;
  background: rgba(217, 70, 239, 0.18);
  color: #f5d0fe;
  font:
    700 0.62rem/1 ui-monospace,
    SFMono-Regular,
    Menlo,
    Consolas,
    monospace;
  box-shadow: 0 0 0 1px rgba(15, 23, 42, 0.55);
  pointer-events: none;
}

.map-view__auto-route-click-debug-marker::before,
.map-view__auto-route-click-debug-marker::after {
  content: "";
  position: absolute;
  background: #d946ef;
  pointer-events: none;
}

.map-view__auto-route-click-debug-marker::before {
  width: 0.72rem;
  height: 2px;
}

.map-view__auto-route-click-debug-marker::after {
  width: 2px;
  height: 0.72rem;
}

.map-view__auto-route-click-debug-label {
  padding: 0.1rem 0.35rem;
  border-radius: 0.25rem;
  background: rgba(15, 23, 42, 0.82);
  color: #f5d0fe;
  font:
    600 0.62rem/1.2 ui-monospace,
    SFMono-Regular,
    Menlo,
    Consolas,
    monospace;
  white-space: nowrap;
  pointer-events: none;
}

.map-view__pick--awaiting-profile {
  outline: 1px solid rgba(37, 99, 235, 0.35);
  outline-offset: 1px;
  border-radius: 10px;
}

.map-view__waypoint-marker {
  width: 26px;
  height: 26px;
  border-radius: 50%;
  display: flex;
  align-items: center;
