  border-radius: 999px;
  background: #1d4ed8;
  color: #fff;
  text-shadow: none;
  box-shadow: 0 1px 3px rgba(15, 23, 42, 0.45);
}

.map-view__glb-nametag-host--flat.map-view__glb-nametag-host--peer .map-view__rider-nametag {
